theorem spectrum_blockGen_mem {n : ℕ} (α : ℝ) {z : ℂ}
    (hz : z ∈ spectrum ℂ (blockGen n α)) :
    z.re ≤ -omegaSeq n ∧ Real.sqrt (omegaSeq n) ≤ ‖z‖

theorem spectrum_blockGen_inv_mem {n : ℕ} (α : ℝ) {z : ℂ}
    (hz : z ∈ spectrum ℂ ((blockGen n α)⁻¹)) :
    z.re = -1 ∧ ‖z‖ ≤ 1 / Real.sqrt (omegaSeq n)

theorem l2_opNorm_blockGen_inv_le_v2 {α : ℝ} (hα0 : 0 < α) (hα1 : α < 1) {n : ℕ}
    (hn : 1 ≤ n) :
    ‖(blockGen n α)⁻¹‖ ≤ Real.sqrt (tower (2 * n)) * (1 + 5 * α / (1 - α))

theorem norm_exp_pi_blockGen_inv_le_v2 {α : ℝ} (hα0 : 0 < α) (hα1 : α < 1) {n : ℕ}
    (hn : 1 ≤ n) :
    ‖exp ((Real.pi : ℂ) • (blockGen n α)⁻¹)‖ ≤ (n : ℝ) ^ α

theorem le_norm_exp_pi_blockGen_inv_v2 {α : ℝ} (hα0 : 0 < α) (hα1 : α < 1) {n : ℕ}
    (hn : 1 ≤ n) :
    1 / 50 * (n : ℝ) ^ α ≤ ‖exp ((Real.pi : ℂ) • (blockGen n α)⁻¹)‖

theorem sum_abs_binomCoeff_le_two_rpow {σ : ℝ} (hσ0 : 0 ≤ σ) (hσ1 : σ ≤ 1) {n : ℕ}
    (hn : 1 ≤ n) :
    ∑ r ∈ range n, |binomCoeff r σ| ≤ 2 * (n : ℝ) ^ σ

theorem l2_opNorm_fromBlocks_diag_le {A : Matrix m₁ m₁ ℂ} {D : Matrix m₂ m₂ ℂ}
    {C : ℝ} (hC : 0 ≤ C) (hA : ‖A‖ ≤ C) (hD : ‖D‖ ≤ C) :
    ‖Matrix.fromBlocks A 0 0 D‖ ≤ C

theorem l2_opNorm_coordProjZ_sub_le {α : ℝ} (hα0 : 0 < α) (hα1 : α < 1) {n : ℕ}
    (k : Fin n) :
    ‖coordProjZ n α (2 * (k : ℕ)) - coordProjZ n 0 (2 * (k : ℕ))‖ ≤ 2 * α / (1 - α)

theorem l2_opNorm_prefixZ_sub_even_le {α : ℝ} (hα0 : 0 < α) (hα1 : α < 1) {n k : ℕ}
    (hk : k ≤ n) :
    ‖prefixZ n α (2 * k) - prefixZ n 0 (2 * k)‖ ≤ 3 * α / (1 - α)

theorem l2_opNorm_prefixZ_sub_le {α : ℝ} (hα0 : 0 < α) (hα1 : α < 1) {n k : ℕ}
    (hk : k ≤ 2 * n) :
    ‖prefixZ n α k - prefixZ n 0 k‖ ≤ 5 * α / (1 - α)
